def edit_target(artist, path, role, source=None, value=None):
    artist._graphunslopify_text_target = {
        "path": path,
        "role": role,
        "source": source,
        "editable": path is not None,
    }
    if value is not None:
        artist._graphunslopify_text_target["value"] = value
    return artist


def series_artist(artist, source, suffix="", legend=True):
    if source is not None:
        for target in artist if isinstance(artist, list) else [artist]:
            target._graphunslopify_legend_identity = {
                "series": str(source),
                "suffix": suffix,
                "legend": legend,
            }
    return artist


def layer_artist(artist, index):
    layer = RUN_REPORT["spec"]["layers"][index]
    if layer.get("label"):
        target = {
            "path": ["layers", index, "label"],
            "role": "layer_label",
            "source": {"layer": index, "mark": layer["mark"]},
        }
        for item in artist if isinstance(artist, list) else [artist]:
            item._graphunslopify_legend_text_target = target
    return artist


def legend_handle_key(handle, label):
    identity = getattr(handle, "_graphunslopify_legend_identity", None)
    target = getattr(handle, "_graphunslopify_legend_text_target", None)
    if identity is not None:
        return ("series", identity["series"])
    if target is not None:
        return ("layer", target["source"]["layer"])
    return ("external", label)


def source_legend_handles(axes):
    ordinary, labels = axes.get_legend_handles_labels()
    public = {id(handle): label for handle, label in zip(ordinary, labels, strict=False)}
    handles, names, seen = [], [], set()
    for handle in [*axes.get_children(), *axes.containers]:
        identity = getattr(handle, "_graphunslopify_legend_identity", None)
        include = (
            identity.get("legend", True)
            if identity is not None
            else (
                id(handle) in public
                or getattr(handle, "_graphunslopify_legend_text_target", None) is not None
            )
        )
        if include and id(handle) not in seen:
            handles.append(handle)
            names.append(public.get(id(handle), handle.get_label()))
            seen.add(id(handle))
    return handles, names


def legend_alias(source):
    key = str(source)
    return next(
        (
            item["text"]
            for item in RUN_REPORT["spec"]["legend"].get("labels", [])
            if item["series"] == key
        ),
        key,
    )


def legend_alias_path(source):
    labels = RUN_REPORT["spec"]["legend"].get("labels", [])
    index = next(
        (index for index, item in enumerate(labels) if item["series"] == str(source)), len(labels)
    )
    return ["legend", "labels", index, "text"]


def validate_legend_aliases(frame):
    labels = RUN_REPORT["spec"]["legend"].get("labels", [])
    if not labels:
        return
    if GROUP is None or GROUP not in frame:
        raise ValueError("Legend display names require a source grouping column")
    names = [str(name) for name in series_names(frame)]
    if len(set(names)) != len(names):
        raise ValueError("Source series IDs have ambiguous string representations")
    requested = [item["series"] for item in labels]
    if len(set(requested)) != len(requested):
        raise ValueError("Each source series may have only one legend display name")
    unknown = sorted(set(requested) - set(names))
    if unknown:
        raise ValueError(f"Legend display names refer to unknown source series: {unknown}")
    if any(not item["text"].strip() for item in labels):
        raise ValueError("Legend display names must contain visible text")
    displayed = [legend_alias(name).strip() for name in names]
    if len(set(displayed)) != len(displayed):
        raise ValueError("Legend display names must uniquely identify source series")


def disclose_legend_aliases(description):
    labels = RUN_REPORT["spec"]["legend"].get("labels", [])
    if not labels:
        return description
    mappings = [f"{item['text']} means source series {item['series']}" for item in labels]
    return description + " Display names: " + "; ".join(mappings) + "."


PANEL_SOURCE_KEYS = []
PANEL_ORIGINAL_NAMES = []


def metric_label(source):
    labels = RUN_REPORT["spec"].get("repeat", {}).get("labels", [])
    return next((item["text"] for item in labels if item["field"] == str(source)), pretty(source))


def metric_label_path(source):
    labels = RUN_REPORT["spec"].get("repeat", {}).get("labels", [])
    index = next((i for i, item in enumerate(labels) if item["field"] == str(source)), len(labels))
    return ["repeat", "labels", index, "text"]


def facet_key(item):
    return tuple((field, item[field]) for field in ("value", "row") if field in item)


def panel_label_value(index, original):
    labels = RUN_REPORT["spec"].get("facet", {}).get("labels", [])
    if not labels:
        return str(original)
    key = facet_key(PANEL_SOURCE_KEYS[index])
    return next((item["text"] for item in labels if facet_key(item) == key), str(original))


def mark_panel_text(artist, index):
    spec = RUN_REPORT["spec"]
    if "repeat" in spec:
        field = spec["repeat"]["fields"][index]
        return edit_target(
            artist, metric_label_path(field), "metric_label", field, metric_label(field)
        )
    if "facet" in spec:
        labels = spec["facet"].get("labels", [])
        source = PANEL_SOURCE_KEYS[index]
        slot = next(
            (i for i, item in enumerate(labels) if facet_key(item) == facet_key(source)),
            len(labels),
        )
        return edit_target(
            artist,
            ["facet", "labels", slot, "text"],
            "panel_title",
            source,
            panel_label_value(index, PANEL_ORIGINAL_NAMES[index]),
        )
    return artist


def validate_panel_aliases(frame, blocks):
    spec = RUN_REPORT["spec"]
    repeat = spec.get("repeat", {})
    labels = repeat.get("labels", [])
    if labels:
        fields = repeat["fields"]
        requested = [item["field"] for item in labels]
        if len(set(fields)) != len(fields) or len(set(requested)) != len(requested):
            raise ValueError("Repeated metric labels require unique source fields and overrides")
        if any(field not in fields or field not in frame for field in requested):
            raise ValueError("Metric display names refer to unknown prepared source fields")
        shown = [metric_label(field).strip() for field in fields]
        if any(not item["text"].strip() for item in labels) or len(set(shown)) != len(shown):
            raise ValueError(
                "Metric display names must visibly and uniquely identify source fields"
            )
    facet = spec.get("facet", {})
    labels = facet.get("labels", [])
    if labels:
        keys = [facet_key(item) for item in PANEL_SOURCE_KEYS]
        requested = [facet_key(item) for item in labels]
        if len(set(keys)) != len(keys) or len(set(requested)) != len(requested):
            raise ValueError(
                "Facet display names require unambiguous source values and unique overrides"
            )
        if any(("row" in item) != ("rows" in facet) for item in labels):
            raise ValueError(
                "Facet display names must include row values exactly for two-dimensional facets"
            )
        if any(key not in keys for key in requested):
            raise ValueError("Facet display names refer to unknown prepared source panels")
        shown = [panel_label_value(i, name).strip() for i, (name, _) in enumerate(blocks)]
        if any(not item["text"].strip() for item in labels) or len(set(shown)) != len(shown):
            raise ValueError("Facet display names must visibly and uniquely identify source panels")


def disclose_panel_aliases(description):
    spec = RUN_REPORT["spec"]
    mappings = [
        f"{item['text']} means source metric {item['field']}"
        for item in spec.get("repeat", {}).get("labels", [])
    ]
    facet = spec.get("facet", {})
    for item in facet.get("labels", []):
        source = f"{facet['by']}={item['value']}"
        if "row" in item:
            source += f", {facet['rows']}={item['row']}"
        mappings.append(f"{item['text']} means source panel {source}")
    return (
        description
        if not mappings
        else description + " Panel display names: " + "; ".join(mappings) + "."
    )


def new_report():
    return {
        "schema_version": 1,
        "tool": TOOL,
        "spec_hash": SPEC_HASH,
        "spec": json.loads(SPEC_JSON),
        "status": "incomplete",
        "ok": False,
        "data": {},
        "environment": None,
        "findings": [dict(f) for f in STATIC_FINDINGS],
        "inspection": {"available": None, "checked": False},
        "panels": [],
        "claims": [],
        "significance": [],
        "annotations": [],
        "outputs": [],
        "skipped_outputs": [],
        "untested": [],
        "alt_text": "",
    }


RUN_REPORT = new_report()
CURRENT_PANEL = 0


def finding(severity, code, message):
    item = {
        "severity": severity,
        "code": code,
        "message": message,
        **DIAGNOSTIC_ADVICE.get(code, UNKNOWN_DIAGNOSTIC),
    }
    if item not in RUN_REPORT["findings"]:
        RUN_REPORT["findings"].append(item)


def diagnostic_text(code, message, severity="warning"):
    advice = DIAGNOSTIC_ADVICE.get(code, UNKNOWN_DIAGNOSTIC)
    return (
        f"{severity.upper()} [{code}] {message}\n"
        f"  Why it matters: {advice['consequence']}\n"
        f"  Recommended correction: {advice['correction']}"
    )


def record_output(path):
    path = Path(path)
    if path.suffix.lower() == ".svg":
        text = path.read_text(encoding="utf8")
        title_id, description_id = f"title-{SPEC_HASH}", f"description-{SPEC_HASH}"
        if f'<desc id="{description_id}">' not in text:
            end = text.index(">", text.index("<svg "))
            attributes = (
                f' role="img" aria-labelledby="{title_id}" aria-describedby="{description_id}"'
            )
            text = text[:end] + attributes + text[end:]
            text = text.replace("<title>", f'<title id="{title_id}">', 1)
            description = f'<desc id="{description_id}">{escape(ALT_TEXT)}</desc>'
            text = text.replace("</title>", "</title>\n " + description, 1)
            # Normalize path formatting, preserving meaningful metadata whitespace.
            text = re.sub(
                r'(<path\b[^>]*\bd=")([^"]*)(")',
                lambda m: m[1] + "\n".join(line.rstrip() for line in m[2].split("\n")) + m[3],
                text,
            )
            path.write_text(text, encoding="utf8")
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(65536), b""):
            digest.update(block)
    RUN_REPORT["outputs"].append(
        {
            "path": str(path),
            "format": path.suffix[1:],
            "sha256": digest.hexdigest(),
            "bytes": path.stat().st_size,
        }
    )


def skip_output(kind, reason):
    RUN_REPORT["skipped_outputs"].append({"format": kind, "reason": reason})
    finding("warning", "output_skipped", f"{kind}: {reason}")


def significance_result(left, right, **details):
    item = {"panel": CURRENT_PANEL, "pair": [str(left), str(right)], **details}
    # Insets and broken axes redraw the same logical comparison.
    RUN_REPORT["significance"] = [
        old
        for old in RUN_REPORT["significance"]
        if (old["panel"], old["pair"]) != (item["panel"], item["pair"])
    ]
    RUN_REPORT["significance"].append(item)


def describe_panels(blocks):
    global Y_FIELD, SAMPLE_SIZE_TEXT
    original_y, original_n = Y_FIELD, SAMPLE_SIZE_TEXT
    descriptions = []
    try:
        for index, (name, frame) in enumerate(blocks):
            if "REPEAT_FIELDS" in globals():
                Y_FIELD = name
            if frame.empty:
                reason = f"panel {name} has no data"
                finding("warning", "empty_panel", reason)
                RUN_REPORT["untested"].append(reason)
            summary = summarise(frame) if not frame.empty and "aggregation" in RUN_REPORT["spec"] and RUN_REPORT["spec"]["kind"] != "heatmap" else frame
            label = str(name) if name is not None else None
            panel = {"index": index, "name": label, "metric": Y_FIELD}
            RUN_REPORT["panels"].append(panel)
            verify_claims(summary)
            for claim in CLAIMS:
                verdict, detail = check_claim(summary, claim)
                measured = _interval_overlap(summary, claim["subject"], claim.get("reference"))
                claim["_verdict"], claim["_overlap"] = verdict, measured
                record = {k: v for k, v in claim.items() if not k.startswith("_")}
                record.update({"panel": index, "metric": Y_FIELD, "detail": detail,
                               "verdict": "untested" if verdict is None else "holds" if verdict else "fails",
                               "interval_overlap": measured})
                RUN_REPORT["claims"].append(record)
            # Keep the original single-panel description byte-for-byte where possible.
            SAMPLE_SIZE_TEXT = original_n if len(blocks) == 1 else ""
            body = "No data." if frame.empty else alt_text(summary)
            if len(blocks) > 1:
                body = body.removeprefix(ENCODING_SENTENCE).strip()
                body = f"Panel {label if label is not None else index + 1}: {body}"
            descriptions.append(body)
    finally:
        Y_FIELD, SAMPLE_SIZE_TEXT = original_y, original_n
    if len(blocks) == 1:
        description = descriptions[0]
    else:
        counts = f" {original_n}." if original_n else ""
        description = ENCODING_SENTENCE + counts + " " + " ".join(descriptions)
    if AUTHOR_CONTEXT:
        description += f" {AUTHOR_CONTEXT}"
    return description


def finish_report():
    capture_environment()
    RUN_REPORT.pop("_execution_policy", None)
    RUN_REPORT["script"] = {"sha256": script_fingerprint()}
    RUN_REPORT["data"] = {"path": DATA_PATH, "sha256_prefix": DATA_HASH, "counts": dict(ROW_COUNTS)}
    RUN_REPORT["alt_text"] = ALT_TEXT
    for field, counts in ROW_COUNTS.get("measurements", {}).items():
        if counts["nonfinite"]:
            finding("warning", "nonfinite_measurements", f"{counts['nonfinite']} non-finite measurements in {field}")
    if ROW_COUNTS.get("missing_plot_keys", 0):
        finding("warning", "missing_plot_keys", f"{ROW_COUNTS['missing_plot_keys']} rows lack plotting keys")
    if ROW_COUNTS.get("finite") == 0:
        RUN_REPORT["untested"].append("no finite measurements in the requested value field")
    if ROW_COUNTS.get("prepared", 0) and ROW_COUNTS.get("missing_plot_keys") == ROW_COUNTS["prepared"]:
        RUN_REPORT["untested"].append("no assignable plotting keys")
    if ROW_COUNTS.get("unlisted_series"):
        finding("warning", "unlisted_series_retained", "Unlisted series were retained: " + ", ".join(ROW_COUNTS["unlisted_series"]))
    sizes = ROW_COUNTS.get("sample_sizes", [])
    if sizes and min(sizes) != max(sizes):
        finding("warning", "unequal_sample_sizes", "Sample sizes differ between plotted points")
    if ROW_COUNTS.get("missing_unit_ids", 0):
        finding("warning", "missing_unit_ids", f"{ROW_COUNTS['missing_unit_ids']} rows lack a declared unit ID")
    if RUN_REPORT["spec"].get("uncertainty") and sizes and min(sizes) < 2:
        RUN_REPORT["untested"].append("uncertainty: fewer than two observations at one or more points")
        finding("warning", "uncertainty_unavailable", RUN_REPORT["untested"][-1])
    failed = (any(f["severity"] == "error" for f in RUN_REPORT["findings"])
              or any(c["verdict"] == "fails" for c in RUN_REPORT["claims"]))
    incomplete = (not RUN_REPORT["inspection"]["checked"] or bool(RUN_REPORT["untested"])
                  or bool(RUN_REPORT["skipped_outputs"])
                  or any(c["verdict"] == "untested" for c in RUN_REPORT["claims"])
                  or any(c["status"] == "untested" for c in RUN_REPORT["significance"]))
    RUN_REPORT["status"] = "failed" if failed else "incomplete" if incomplete else "passed"
    RUN_REPORT["ok"] = RUN_REPORT["status"] == "passed"
    return RUN_REPORT


def run_cli(argv=None):
    global RUN_REPORT, DATA_HASH, ALT_TEXT, SAMPLE_SIZE_TEXT, Y_FIELD  # noqa: PLW0603 -- reset the bound program context
    parser = argparse.ArgumentParser(
        description="Render this figure and write its verification evidence"
    )
    policy = parser.add_mutually_exclusive_group()
    policy.add_argument(
        "--strict",
        action="store_true",
        default=True,
        help="reject failed or incomplete verification (default)",
    )
    policy.add_argument(
        "--no-strict",
        dest="strict",
        action="store_false",
        help="explicit legacy opt-out; keep failed/incomplete reports without verification exit 2",
    )
    parser.add_argument(
        "--fail-on-warning", action="store_true", help="strict mode, also rejecting warnings"
    )
    parser.add_argument(
        "--report", default=f"{STEM}.report.json", metavar="FILE", help="JSON report destination"
    )
    parser.add_argument(
        "--json", action="store_true", help="print only JSON on stdout; rendering logs go to stderr"
    )
    args = parser.parse_args(argv)
    if args.report == "-":
        parser.error("use --json for JSON stdout; --report expects a file path")
    RUN_REPORT = new_report()
    RUN_REPORT["_execution_policy"] = {
        "strict": args.strict or args.fail_on_warning,
        "fail_on_warning": args.fail_on_warning,
        "source": "cli",
    }
    DATA_HASH, ALT_TEXT, SAMPLE_SIZE_TEXT = "unknown", "", ""
    Y_FIELD = RUN_REPORT["spec"]["y"]["field"]
    ROW_COUNTS.clear()
    globals().get("MISSING_INTERVALS", {}).clear()
    logs = io.StringIO()
    runtime_failure = False
    try:
        with contextlib.redirect_stdout(logs):
            main()
    except (Exception, SystemExit) as problem:  # noqa: BLE001 -- CLI records all runtime failures
        runtime_failure = True
        finding("error", "runtime_error", str(problem) or type(problem).__name__)
    report = finish_report()
    rejected = ((args.strict or args.fail_on_warning) and not report["ok"]) or (
        args.fail_on_warning and any(f["severity"] == "warning" for f in report["findings"])
    )
    report["exit_code"] = 1 if runtime_failure else 2 if rejected else 0
    report["policy"] = {
        "strict": args.strict or args.fail_on_warning,
        "fail_on_warning": args.fail_on_warning,
        "passed": report["exit_code"] == 0,
    }
    encoded = json.dumps(report, indent=2, allow_nan=False) + "\n"
    path = Path(args.report)
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(encoded, encoding="utf8")
    except OSError as problem:
        print(f"could not write report {path}: {problem}", file=sys.stderr)
        return 1
    if logs.getvalue():
        print(logs.getvalue(), end="", file=sys.stderr if args.json else sys.stdout)
    if args.json:
        print(encoded, end="")
    else:
        print(f"verification: {report['status']}; wrote {path}")
        for item in report["findings"]:
            print(
                diagnostic_text(item["code"], item["message"], item["severity"]),
                file=sys.stderr if item["code"] == "runtime_error" else sys.stdout,
            )
        for reason in report["untested"]:
            print(diagnostic_text("check_untested", reason))
        for claim in report["claims"]:
            if claim["verdict"] in {"fails", "untested"}:
                print(
                    diagnostic_text(
                        "claim_failed" if claim["verdict"] == "fails" else "check_untested",
                        claim.get("detail", claim["kind"]),
                        "error" if claim["verdict"] == "fails" else "warning",
                    )
                )
    return report["exit_code"]

IDENTITY_FIELDS = ["model"]
REQUIRED_IDENTITY_FIELDS = ["model"]
IDENTITY_CONFLICTS = []


def normalize_identities(frame, *, final=True):
    if IDENTITY_CONFLICTS:
        raise ValueError(
            "Columns cannot serve both identifier and measurement roles: "
            + ", ".join(IDENTITY_CONFLICTS)
        )
    for key in ("series_order", "category_order"):
        order = RUN_REPORT["spec"].get(key)
        if order is not None and len(order) != len(set(order)):
            raise ValueError(key + " must contain unique identifiers")
    source = frame.copy()
    lexical = source.attrs.pop("_graphunslopify_identity_rows", {})
    for field in IDENTITY_FIELDS:
        if field not in source:
            if final and field in REQUIRED_IDENTITY_FIELDS:
                raise ValueError(f"Required identifier column {field} is missing")
            continue
        values = source[field].tolist()
        if field in lexical:
            values = [lexical[field][int(index)] for index in source.index]
        seen = {}

        def as_identifier(value, field=field, seen=seen):
            if not pd.api.types.is_scalar(value):
                raise ValueError(f"Identifier {field} must contain scalar values")
            if pd.isna(value):
                return None
            if isinstance(value, (float, np.floating)) and not np.isfinite(value):
                raise ValueError(f"Numeric identifier {field} must be finite")
            text = str(value)
            if not text.strip():
                raise ValueError(f"Identifier {field} must be nonempty")
            if text in seen and seen[text] != value:
                raise ValueError(
                    f"Distinct identifiers in {field} collide as textual name {text!r}"
                )
            seen[text] = value
            return text

        normalized = [as_identifier(value) for value in values]
        dtype = source[field].dtype
        if isinstance(dtype, pd.CategoricalDtype):
            categories = [as_identifier(value) for value in dtype.categories]
            source[field] = pd.Categorical(normalized, categories=categories, ordered=dtype.ordered)
        else:
            source[field] = pd.Series(normalized, index=source.index, dtype=object)
        if field in REQUIRED_IDENTITY_FIELDS and source[field].isna().any():
            raise ValueError(f"Required identifier {field} is missing for retained observations")
    return source


def load():
    global DATA_HASH
    with pd.io.common.get_handle(DATA_PATH, "rb", compression=None, is_text=False) as raw:
        snapshot = raw.handle.read()
        decoded = raw.compression.get("method") is not None
    DATA_HASH = hashlib.sha256(snapshot).hexdigest()[:16]
    # Keep pandas' filename-based compression behavior on the byte snapshot.
    compression = None if decoded else pd.io.common.infer_compression(DATA_PATH, "infer")
    with pd.io.common.get_handle(io.BytesIO(snapshot), "rb", compression=compression, is_text=False) as handle:
        payload = handle.handle.read()
    df = pd.read_csv(io.BytesIO(payload))
    # Preserve names from the same bytes; filters still see the typed frame.
    names = pd.read_csv(io.BytesIO(payload), dtype={field: "string" for field in IDENTITY_FIELDS})
    if len(names) != len(df):
        raise ValueError("Identifier and measurement rows do not align")
    df = df.reset_index(drop=True)
    df.attrs["_graphunslopify_identity_rows"] = {
        field: names[field].to_numpy(dtype=object, na_value=None).tolist()
        for field in IDENTITY_FIELDS if field in names}
    ROW_COUNTS.clear()
    ROW_COUNTS["read"] = len(df)
    return df


def validate_numeric_domains(frame):
    for field in ["epoch"]:
        if field not in frame:
            continue
        measured = pd.to_numeric(frame[field], errors="coerce")
        values = measured.to_numpy(dtype=float, na_value=np.nan)
        if (frame[field].notna() & measured.isna()).any() or np.isinf(values).any():
            raise ValueError(f"Field {field} requires finite numeric measurements or missing values; filter invalid observations explicitly")
        if isinstance(measured.dtype, pd.api.extensions.ExtensionDtype) and measured.isna().any():
            measured = measured.astype(object).where(measured.notna(), np.nan)
        frame[field] = measured


def prepare(df):
    ROW_COUNTS["after_filter"] = len(df)
    df = normalize_identities(df)
    validate_numeric_domains(df)
    return df


ROW_COUNTS = {}
SAMPLE_SIZE_TEXT = ""

def report_counts(frame):
    global SAMPLE_SIZE_TEXT
    SAMPLE_SIZE_TEXT = ""
    ROW_COUNTS["prepared"] = len(frame)
    print(f"data: {DATA_PATH}, sha256 {DATA_HASH}")
    print(f"  {ROW_COUNTS.get('read', len(frame))} rows read")
    print(f"  {ROW_COUNTS.get('after_filter', len(frame))} rows after filter (" + "none" + ")")
    if len(frame) != ROW_COUNTS.get("after_filter", len(frame)):
        print(f"  {len(frame)} rows after reshape and transform")
    plot_keys = [field for field in ["epoch", "model"] if field in frame]
    ROW_COUNTS["missing_plot_keys"] = int(frame[plot_keys].isna().any(axis=1).sum()) if plot_keys else 0
    if ROW_COUNTS["missing_plot_keys"]:
        print(f"warning: {ROW_COUNTS['missing_plot_keys']} rows lack plotting keys and cannot be assigned to a point, panel or series")
    if SERIES_ORDER is not None and GROUP in frame:
        ROW_COUNTS["unlisted_series"] = [str(name) for name in frame[GROUP].dropna().unique() if name not in SERIES_ORDER]
    ROW_COUNTS["measurements"] = {}
    for field in ["accuracy"]:
        if field not in frame:
            continue
        finite = np.isfinite(pd.to_numeric(frame[field], errors="coerce").to_numpy(dtype=float))
        counts = {"finite": int(finite.sum()), "nonfinite": int((~finite).sum())}
        ROW_COUNTS["measurements"][field] = counts
        print(f"  {counts['finite']} rows with a finite {field} ({counts['nonfinite']} non-finite)")
    if "accuracy" in ROW_COUNTS["measurements"]:
        ROW_COUNTS.update(ROW_COUNTS["measurements"]["accuracy"])
    sizes = []
    keys = ["epoch", "model"]
    for field in ["accuracy"]:
        if field not in frame:
            continue
        source = summary_input(frame, field)
        measured = source.assign(_finite=np.isfinite(pd.to_numeric(source[field], errors="coerce")).astype(int))
        sizes.extend(measured.groupby(keys, sort=False, observed=True)["_finite"].sum().tolist())
    ROW_COUNTS["sample_sizes"] = [int(n) for n in sizes]
    if sizes:
        low, high = int(min(sizes)), int(max(sizes))
        SAMPLE_SIZE_TEXT = f"n = {low} per point" if low == high else f"n ranges from {low} to {high} across {len(sizes)} points"
        print(f"  {SAMPLE_SIZE_TEXT}")
        if low != high:
            print("warning: sample sizes differ between groups")


def summary_input(frame, field):
    measured = frame.copy()
    measured[field] = pd.to_numeric(measured[field], errors="coerce").replace([np.inf, -np.inf], np.nan)
    return measured


def summarise(frame):
    frame = summary_input(frame, Y_FIELD)
    keys = [X_FIELD] + ([GROUP] if GROUP is not None else [])
    # sort=False keeps the file's category order instead of an alphabetical one.
    grouped = frame.groupby(keys, as_index=False, sort=False, observed=True)[Y_FIELD]
    summary = grouped.mean()
    return summary


def locked_appearance(names):
    # A shared lock keeps a model the same colour in figure 1 and figure 7.
    if PALETTE_LOCK is None:
        return None
    try:
        from graphunslopify.lockfile import appearance
    except ImportError:
        print(diagnostic_text("palette_lock_unavailable", "The lockfile appearance helper is unavailable, so palette_lock was ignored."))
        return None
    return appearance(PALETTE_LOCK, [str(n) for n in names])


def series_names(frame):
    if GROUP is None:
        return [None]
    if SERIES_ORDER is not None:
        observed = sorted(frame[GROUP].dropna().unique().tolist(), key=str)
        return [n for n in SERIES_ORDER if n in observed] + [n for n in observed if n not in SERIES_ORDER]
    return sorted(frame[GROUP].dropna().unique().tolist(), key=str)


def series_style(name, index, total):
    locked = LOCKED.get(str(name)) if LOCKED else None
    colour = locked["colour"] if locked else PALETTE[index % len(PALETTE)]
    # Colour alone is not enough in greyscale, so add a second channel.
    if total <= SECOND_CHANNEL_THRESHOLD:
        channel = "-"
    elif EMPHASIS is None:
        channel = LINE_STYLES[index % len(LINE_STYLES)]
    else:
        # The emphasised series keeps the plain form, so the others must skip
        # it. Without this, series zero is also plain and the two collide.
        rest = LINE_STYLES[1:] or LINE_STYLES
        channel = rest[index % len(rest)]
    if locked and total > SECOND_CHANNEL_THRESHOLD:
        channel = locked["linestyle"]
    if name == EMPHASIS:
        channel = "-"
    if EMPHASIS is None:
        style = {"colour": colour, "width": 1.2, "alpha": 1.0, "zorder": 2}
    elif name == EMPHASIS:
        style = {"colour": colour, "width": 1.9, "alpha": 1.0, "zorder": 3}
    else:
        style = {"colour": colour, "width": 0.9, "alpha": RECEDED_ALPHA, "zorder": 1}
    style["linestyle"] = channel
    return style


def draw_panel(ax, df):
    frame = summarise(df)
    names = series_names(frame)
    for index, name in enumerate(names):
        block = frame[frame[GROUP] == name]
        block = block.sort_values(X_FIELD)
        style = series_style(name, index, len(names))
        _annotation_curve, = ax.plot(
            block[X_FIELD],
            block[Y_FIELD],
            label=str(name),
            color=style["colour"],
            linewidth=style["width"],
            alpha=style["alpha"],
            zorder=style["zorder"],
            linestyle=style["linestyle"],
            marker="o" if len(block) == 1 else None,
        )
        series_artist(_annotation_curve, name)


