def heading_dollars(text):
    return text.count("$") - text.count(r"\$")


def literal_heading_lines(lines, original):
    # An originally literal paragraph must not acquire a MathText line.
    index = 0
    while index < len(lines):
        count = heading_dollars(lines[index])
        if count == 0 or count % 2:
            index += 1
            continue
        line = lines[index]
        cuts = [
            match
            for match in re.finditer(r"\s+", line)
            if heading_dollars(line[: match.start()]) % 2
        ]
        if cuts:
            cut = cuts[-1]
            lines[index : index + 1] = [line[: cut.start()], line[cut.end() :]]
            index += 2
            continue
        # A dollar pair inside one word cannot be split without changing it.
        # Keep it with an odd-dollar neighbor; ordinary inspection still owns
        # acceptance if the resulting complete wording cannot fit the column.
        odd = [i for i, text in enumerate(lines) if heading_dollars(text) % 2]
        if not odd:
            return [original]
        neighbor = min(odd, key=lambda i: abs(i - index))
        low, high = sorted((index, neighbor))
        lines[low : high + 1] = [" ".join(lines[low : high + 1])]
        index = low + 1
    return lines


def wrap_heading(original, artist, renderer, width):
    from matplotlib.text import Text

    probe = Text(
        fontproperties=artist.get_fontproperties(),
        usetex=artist.get_usetex(),
        parse_math=artist.get_parse_math(),
    )
    probe.set_figure(artist.get_figure())
    parse_math, use_tex = artist.get_parse_math(), artist.get_usetex()
    lines = []
    for paragraph in original.split("\n"):
        dollars = heading_dollars(paragraph)
        mathematical = (parse_math or use_tex) and dollars > 0 and dollars % 2 == 0
        probe.set_parse_math(parse_math and mathematical)
        paragraph_lines = []
        tokens, token = [], ""
        math_mode, depth, escaped, space = False, 0, False, False
        for position, char in enumerate(paragraph):
            separable = char.isspace() and not math_mode and depth == 0 and not escaped
            if token and separable != space:
                tokens.append(token)
                token = ""
            token += char
            space = separable
            dollar_boundary = (
                not escaped if use_tex else position == 0 or paragraph[position - 1] != "\\"
            )
            if char == "$" and mathematical and dollar_boundary:
                math_mode = not math_mode
            elif not escaped:
                if char == "{" and (math_mode or use_tex):
                    depth += 1
                elif char == "}" and depth:
                    depth -= 1
            escaped = char == "\\" and not escaped
        if token:
            tokens.append(token)
        line, separator = "", ""
        for token in tokens:
            if token.isspace():
                separator += token
                continue
            candidate = line + separator + token
            probe.set_text(
                candidate.replace(r"\$", "$")
                if parse_math and not mathematical and not use_tex
                else candidate
            )
            if line and probe.get_window_extent(renderer).width > width:
                paragraph_lines.append(line)
                line = token
            else:
                line = candidate
            separator = ""
        paragraph_lines.append(line + separator)
        if parse_math and not mathematical and not use_tex and dollars > 1:
            paragraph_lines = literal_heading_lines(paragraph_lines, paragraph)
        lines.extend(paragraph_lines)
    return "\n".join(lines)


def fit_headings(fig):
    minimum_heights = {ax: getattr(ax, "_graphunslopify_heading_height", ax.bbox.height)
                       for ax in fig.axes if ax.get_visible()}
    for attempt in range(8):
        fig.canvas.draw()
        renderer = fig.canvas.get_renderer()
        candidates = [(text, fig.bbox.width * 0.94, False) for text in fig.texts
                      if getattr(text, "_graphunslopify_text_target", {}).get("role") == "title"]
        for ax in fig.axes:
            if not ax.get_visible():
                continue
            candidates.extend((text, ax.bbox.width * 0.98, False)
                              for text in (ax.title, ax._left_title, ax._right_title))
            if ax.axison:
                # Axis wording may use free margins beyond the data rectangle.
                available_height = max(ax.bbox.height, minimum_heights[ax])
                grid = ax.get_subplotspec()
                if grid is not None:
                    rows = grid.get_gridspec().nrows
                    bottom = fig.bbox.y0 + fig.bbox.height * (1 - grid.rowspan.stop / rows)
                    top = fig.bbox.y0 + fig.bbox.height * (1 - grid.rowspan.start / rows)
                    center = ax.yaxis.label.get_transform().transform(ax.yaxis.label.get_position())[1]
                    available_height = max(available_height, 2 * min(center - bottom, top - center))
                candidates.extend([(ax.xaxis.label, ax.bbox.width * 0.98, False),
                                   (ax.yaxis.label, available_height * 0.98, True)])
        changed = False
        for artist, width, vertical in candidates:
            target = getattr(artist, "_graphunslopify_text_target", {})
            if target.get("role") not in {"title", "panel_title", "axis_label", "metric_label"}:
                continue
            if not artist.get_visible() or not artist.get_text().strip() or width <= 0:
                continue
            box = artist.get_window_extent(renderer)
            if (box.height if vertical else box.width) <= width:
                continue
            original = getattr(artist, "_graphunslopify_heading_original", artist.get_text())
            wrapped = wrap_heading(original, artist, renderer, width)
            if wrapped != artist.get_text():
                artist._graphunslopify_heading_original = original
                artist.set_text(wrapped)
                changed = True
        if not changed:
            return
        fig.canvas.draw()
        renderer = fig.canvas.get_renderer()
        row_heights = {}
        for ax, minimum in minimum_heights.items():
            grid = ax.get_subplotspec()
            if grid is None:
                continue
            ax._graphunslopify_heading_height = minimum
            box = ax.get_tightbbox(renderer)
            if box is None:
                continue
            height = minimum + max(0, box.y1 - ax.bbox.y1) + max(0, ax.bbox.y0 - box.y0)
            rows = list(grid.rowspan)
            for row in rows:
                row_heights[row] = max(row_heights.get(row, 0), height / len(rows))
        title_height = max((text.get_window_extent(renderer).height for text in fig.texts
                            if text.get_visible() and getattr(text, "_graphunslopify_text_target", {}).get("role") == "title"), default=0)
        required_height = sum(row_heights.values()) + title_height + fig.dpi * 0.3
        if row_heights and required_height > fig.bbox.height + 1:
            fig.set_size_inches(fig.get_figwidth(), required_height / fig.dpi)
        fig.tight_layout()


def decorate_panel(ax, frame, panel_label, show_x=True, show_y=True):
    if show_x:
        ax.set_xlabel("Training epoch")
        edit_target(ax.xaxis.label, ["x", "label"], "axis_label", "epoch")
    if show_y:
        ax.set_ylabel("Test accuracy (%)")
        edit_target(ax.yaxis.label, ["y", "label"], "axis_label", "accuracy")
    ax.set_ylim(0, 90)
    ax.grid(True, linewidth=0.4, alpha=0.5)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    if panel_label is not None:
        mark_panel_text(ax.set_title(str(panel_label), loc="left", fontsize=PANEL_LETTER_PT), CURRENT_PANEL)


def add_legend(fig, ax, frame, layout_columns=None):
    handles, labels = source_legend_handles(ax)
    if not handles:
        return
    identities, displayed, label_targets = [], [], []
    for handle, label in zip(handles, labels):
        identity = getattr(handle, "_graphunslopify_legend_identity", None)
        source = identity["series"] if identity is not None else None
        suffix = identity.get("suffix", "") if identity is not None else ""
        identities.append(source)
        label_targets.append(getattr(handle, "_graphunslopify_legend_text_target", None))
        displayed.append(label if source is None else legend_alias(source) + suffix)
    if (RUN_REPORT["spec"]["legend"].get("labels") or any(label_targets)) and len({name.strip() for name in displayed}) != len(displayed):
        raise ValueError("Legend display names collide with another visible legend entry")
    legend = ax.legend(
        handles,
        [f"Series {index}" for index in range(len(handles))],
        title=None,
        frameon=False,
        loc="best",
        ncol=layout_columns or 1,
    )
    for text, source, original, shown, target in zip(legend.get_texts(), identities, labels, displayed, label_targets):
        text.set_text(shown)
        if source is None and target is not None:
            edit_target(text, target["path"], target["role"], target["source"])
        else:
            edit_target(text, None if source is None else legend_alias_path(source), "legend_entry", original if source is None else source)
    edit_target(legend.get_title(), ["legend", "title"], "legend_title")
    legend._graphunslopify_legend_frame = frame
    legend._graphunslopify_panel_legend = False
    return legend


def data_fingerprint():
    # A figure built from a file that has since changed is worse than no
    # figure, because it looks current.
    try:
        with open(DATA_PATH, "rb") as handle:
            digest = hashlib.sha256()
            for block in iter(lambda: handle.read(65536), b""):
                digest.update(block)
        return digest.hexdigest()[:16]
    except OSError:
        return "unreadable"


def script_fingerprint():
    try:
        with open(__file__, "rb") as handle:
            digest = hashlib.sha256()
            for block in iter(lambda: handle.read(65536), b""):
                digest.update(block)
        return digest.hexdigest()
    except (NameError, OSError):
        return None


def _aligned(frame, subject, reference):
    """Require complete, finite x coverage for the named series."""
    if GROUP is None or Y_FIELD not in frame:
        return None
    columns = [subject] if reference is None else [subject, reference]
    selected = frame[frame[GROUP].isin(columns)]
    if (
        selected.empty
        or selected[X_FIELD].isna().any()
        or selected.duplicated([X_FIELD, GROUP]).any()
    ):
        return None
    pivot = selected.pivot_table(
        index=X_FIELD, columns=GROUP, values=Y_FIELD, aggfunc="mean", dropna=False, observed=True
    )
    if any(column not in pivot.columns for column in columns):
        return None
    pair = pivot[columns].sort_index()
    if not len(pair) or not np.isfinite(pair.to_numpy(dtype=float)).all():
        return None
    return pair


def _interval_overlap(frame, subject, reference):
    """How many shared x values have overlapping intervals, or None.

    None when there is nothing to measure: no reference, no grouping, or no
    uncertainty in the spec, in which case _low was never written.
    """
    if reference is None or GROUP is None or "_low" not in frame:
        return None
    lows = frame.pivot_table(
        index=X_FIELD, columns=GROUP, values="_low", aggfunc="mean", observed=True
    )
    highs = frame.pivot_table(
        index=X_FIELD, columns=GROUP, values="_high", aggfunc="mean", observed=True
    )
    for column in (subject, reference):
        if column not in lows.columns or column not in highs.columns:
            return None
    shared = lows.index.intersection(highs.index).sort_values()
    bounds = [
        lows.loc[shared, subject].to_numpy(dtype=float),
        highs.loc[shared, subject].to_numpy(dtype=float),
        lows.loc[shared, reference].to_numpy(dtype=float),
        highs.loc[shared, reference].to_numpy(dtype=float),
    ]
    usable = np.all([np.isfinite(edge) for edge in bounds], axis=0)
    if not usable.any():
        return None
    mine_low, mine_high, their_low, their_high = (edge[usable] for edge in bounds)
    touching = (mine_low <= their_high) & (their_low <= mine_high)
    return int(np.sum(touching)), int(usable.sum())


def overlap_phrase(measured):
    # Counts, not a p-value. Non-overlapping intervals imply a difference;
    # overlapping ones do not imply its absence, and Cumming's mapping from
    # overlap to significance is conditioned on n. Report what was measured.
    if measured is None or measured[0] == 0:
        return None
    return f"the intervals overlap at {measured[0]} of {measured[1]} x values"


def check_claim(frame, claim):
    """Return (holds, detail). None means the claim could not be tested."""
    subject, reference = claim["subject"], claim.get("reference")
    tolerance = claim.get("tolerance") or 0.0
    pair = _aligned(frame, subject, reference)
    if pair is None:
        return (
            None,
            "named series are missing, have incomplete x coverage, duplicate x values, or non-finite measurements",
        )

    mine = pair[subject].to_numpy(dtype=float)
    theirs = pair[reference].to_numpy(dtype=float) if reference else None
    kind = claim["kind"]
    if (
        kind
        in ("gap_widens", "gap_narrows", "monotone_increasing", "monotone_decreasing", "converges")
        and len(mine) < 2
    ):
        return None, "at least two x values are required for a trend claim"

    if kind == "beats_everywhere":
        losses = int(np.sum(mine <= theirs))
        return losses == 0, f"{losses} of {len(mine)} x values are not above {reference}"

    if kind == "beats_on_average":
        gap = float(mine.mean() - theirs.mean())
        return gap > 0, f"mean difference is {gap:+.4g}"

    if kind == "beats_at_end":
        gap = float(mine[-1] - theirs[-1])
        return gap > 0, f"difference at the largest x is {gap:+.4g}"

    if kind in ("gap_widens", "gap_narrows"):
        gap = mine - theirs
        half = max(len(gap) // 2, 1)
        early, late = float(gap[:half].mean()), float(gap[half:].mean())
        change = late - early
        widening = kind == "gap_widens"
        holds = change > 0 if widening else change < 0
        return holds, f"gap moves from {early:+.4g} to {late:+.4g}, a change of {change:+.4g}"

    if kind in ("monotone_increasing", "monotone_decreasing"):
        steps = np.diff(mine)
        rising = kind == "monotone_increasing"
        breaks = int(np.sum(steps < -tolerance if rising else steps > tolerance))
        return breaks == 0, f"{breaks} of {len(steps)} steps go the wrong way"

    if kind == "converges":
        tail = max(len(mine) // 5, 1)
        spread = float(np.abs(mine - theirs)[-tail:].max())
        return spread <= tolerance, f"largest gap over the final fifth is {spread:.4g}"

    if kind == "no_worse_than":
        deficit = float(np.max(theirs - mine))
        return deficit <= tolerance, f"largest shortfall against {reference} is {deficit:.4g}"

    if kind == "within_tolerance":
        spread = float(np.max(np.abs(mine - theirs)))
        return spread <= tolerance, f"largest absolute difference is {spread:.4g}"

    return None, f"no test implemented for {kind}"


def verify_claims(frame):
    """Test every claim. Returns True when none of them failed."""
    if not CLAIMS:
        return True
    print("claims:")
    ok = True
    for claim in CLAIMS:
        holds, detail = check_claim(frame, claim)
        wording = claim["wording"].replace("{reference}", str(claim.get("reference")))
        sentence = f"{claim['subject']} {wording}"
        if holds is None:
            print(f"  UNTESTED  {sentence} ({detail})")
            continue
        if holds:
            print(f"  HOLDS     {sentence} ({detail})")
            overlap = overlap_phrase(
                _interval_overlap(frame, claim["subject"], claim.get("reference"))
            )
            if overlap is not None:
                print(f"            but {overlap}, so the spread does not separate them")
        else:
            ok = False
            print(f"  FAILS     {sentence} ({detail})")
            print("            the figure does not support this. Do not write it in the caption.")
    return ok


def describe_figure(frame):
    """Levels 2 and 3 of the alt text: the numbers and the trend."""
    parts = []
    if SAMPLE_SIZE_TEXT:
        parts.append(SAMPLE_SIZE_TEXT)
    ends, absent = {}, []
    last = frame[X_FIELD].dropna().max() if len(frame) else None
    repeated = False
    for name in series_names(frame):
        block = frame[(frame[GROUP] == name) & (frame[X_FIELD] == last)].dropna(subset=[Y_FIELD])
        if len(block):
            ends[name] = float(block[Y_FIELD].mean())
            repeated = repeated or len(block) > 1
        else:
            absent.append(str(name))
    if ends:
        ranked = sorted(ends.items(), key=lambda kv: -kv[1])
        best, worst = ranked[0], ranked[-1]
        location = f"At the largest {X_LABEL_PLAIN}"
        qualifier = "mean observed values: " if repeated else ""
        if len(ranked) > 1:
            parts.append(f"{location}, {qualifier}{best[0]} is highest at {best[1]:.3g} and {worst[0]} is lowest at {worst[1]:.3g}")
            parts.append(f"a spread of {best[1]-worst[1]:.3g}")
        else:
            parts.append(f"{location}, {qualifier}{best[0]} is {best[1]:.3g}")
    if absent:
        parts.append("No finite measurement at that x for " + ", ".join(absent))
    if not parts:
        return ""
    # Every clause is its own sentence, so a screen reader pauses between them.
    return ". ".join(part[:1].upper() + part[1:] for part in parts) + "."


def alt_text(frame):
    detail = describe_figure(frame)
    body = ENCODING_SENTENCE + (f" {detail}" if detail else "")
    for claim in CLAIMS:
        if claim.get("_verdict") is not True:
            continue
        wording = claim["wording"].replace("{reference}", str(claim.get("reference")))
        sentence = f"{claim['subject']} {wording}"
        # A claim the spread does not separate is not quoted bare. The bands
        # are what persuade a reader to trust the verdict, so a reader who
        # cannot see them is owed the same caveat.
        overlap = overlap_phrase(claim.get("_overlap"))
        if overlap is not None:
            sentence += f", though {overlap}"
        body += " " + sentence[:1].upper() + sentence[1:] + "."
    return body


def metadata_for(fmt):
    # Embedding the spec means a reviewer can recover what produced the figure.
    stamp = f"{TOOL} spec:{SPEC_HASH} data:{DATA_HASH}"
    provenance = json.dumps(
        {
            "schema_version": 1,
            "tool": TOOL,
            "spec_hash": SPEC_HASH,
            "data_sha256_prefix": DATA_HASH,
            "script_sha256": script_fingerprint(),
            "spec": json.loads(SPEC_JSON),
            "alt_text": ALT_TEXT,
            "environment": capture_environment(),
        },
        ensure_ascii=False,
    )
    if fmt == "png":
        return {
            "Software": stamp,
            "Description": SPEC_JSON,
            "Comment": ALT_TEXT,
            "GraphUnslopify": provenance,
        }
    if fmt == "svg":
        return {
            "Creator": stamp,
            "Description": ALT_TEXT,
            "Title": FIGURE_TITLE or Path(STEM).name,
            "Identifier": SPEC_HASH,
            "Source": provenance,
            "Date": None,
        }
    return {
        "Creator": stamp,
        "Subject": SPEC_JSON,
        "Keywords": provenance,
        "Title": FIGURE_TITLE or Path(STEM).name,
        "CreationDate": None,
        "ModDate": None,
    }


def check(fig):
    # Optional. Install graphunslopify for readability and colour checks.
    try:
        from graphunslopify import inspect_figure
    except ImportError:
        print("graphunslopify not installed, skipping figure checks")
        RUN_REPORT["inspection"] = {"available": False, "checked": False}
        finding("warning", "inspection_unavailable", "Install graphunslopify to run figure inspection")
        return True
    paths = [item["path"] for item in RUN_REPORT["outputs"] if item["format"] in {"png", "svg", "pdf"}]
    report = None
    try:
        report = inspect_figure(fig, target_width_in=TARGET_WIDTH_IN, min_text_pt=MIN_TEXT_PT, export_paths=paths)
    except TypeError as error:
        if "export_paths" not in str(error): raise
    if report is None or not getattr(report, "measurements", None) or report.measurements.get("basis") not in {"exports", "unavailable"} or "data_view" not in report.measurements:
        RUN_REPORT["inspection"] = {"available": True, "checked": False}
        finding("warning", "inspection_outdated", "Upgrade graphunslopify: final exported text-size or data-view inspection is unavailable in this checker")
        return False
    print(f"figure checks: {len(report.findings)} finding(s)" if "_execution_policy" in RUN_REPORT else report)
    RUN_REPORT["inspection"] = {"available": True, "checked": report.measurements["basis"] == "exports", "measurements": report.measurements}
    for item in report.findings:
        finding(item.severity, item.code, item.message)
    return report.ok


def panels(df):
    """One entry per panel. Without faceting that is the whole frame."""
    return [(None, df)]


SHARE_X = False
SHARE_Y = False
FACET_COLUMNS = 1


def main():
    global DATA_HASH, ALT_TEXT
    df = prepare(load())
    report_counts(df)
    validate_legend_aliases(df)
    if PALETTE_LOCK is not None and GROUP is not None:
        globals()["LOCKED"] = locked_appearance(
            SERIES_ORDER if SERIES_ORDER is not None else sorted(df[GROUP].dropna().unique(), key=str)
        )
    blocks = panels(df)
    if not blocks: raise ValueError("no usable facet values in the prepared data")
    globals()["PANEL_ORIGINAL_NAMES"] = [name for name, _ in blocks]
    validate_panel_aliases(df, blocks)
    columns = min(FACET_COLUMNS, len(blocks)) if len(blocks) > 1 else 1
    rows = math.ceil(len(blocks) / columns)

    with plt.rc_context(RC_PARAMS):
        fig, axes = plt.subplots(
            rows,
            columns,
            figsize=(FIGSIZE[0], FIGSIZE[1] * rows) if rows > 1 else FIGSIZE,
            sharex=SHARE_X,
            sharey=SHARE_Y,
            squeeze=False,
        )
        flat = list(axes.flat)
        legend_added = False
        for index, (name, block) in enumerate(blocks):
            ax = flat[index]
            globals()["CURRENT_PANEL"] = index
            if block.empty:
                ax.text(0.5, 0.5, "No data", transform=ax.transAxes, ha="center")
                mark_panel_text(ax.set_title(panel_label_value(index, name)), index)
                ax.set_axis_off()
                continue

            draw_panel(ax, block)


            letter = panel_label_value(index, name) if name is not None else None
            show_x = (index // columns) == rows - 1 or not SHARE_X
            show_y = (index % columns) == 0 or not SHARE_Y
            decorate_panel(ax, block, letter, show_x, show_y)
            # One legend for the whole figure; repeating it wastes panel space.
            if not legend_added:
                add_legend(fig, ax, block)
                legend_added = True
        for spare in flat[len(blocks) :]:
            spare.set_visible(False)

        if len(blocks) > 1:
            edit_target(fig.suptitle("Accuracy over training, double column"), ["title"], "title")
        else:
            edit_target(flat[0].set_title("Accuracy over training, double column"), ["title"], "title")
        fit_headings(fig)
        fit_category_labels(fig, flat)
        fig.tight_layout()
        fit_headings(fig)
        description = disclose_panel_aliases(disclose_legend_aliases(describe_panels(blocks)))
        claims_hold = not any(c["verdict"] == "fails" for c in RUN_REPORT["claims"])
        print(f"alt text: {description}")
        ALT_TEXT = description
        capture_environment(fig)
        for fmt in FORMATS:
            path = f"{STEM}.{fmt}"
            meta = metadata_for(fmt)
            fig.savefig(path, bbox_inches="tight", metadata=meta, **({"dpi": DPI} if fmt == "png" else {}))
            record_output(path)
            print(f"wrote {path}")
        check(fig)
    plt.close(fig)


    print(DISCLOSURE)
    print(f"data sha256:{DATA_HASH}")
    if not claims_hold:
        print("at least one claim failed. The caption must not assert it.")


if __name__ == "__main__":
    raise SystemExit(run_cli())
